        public const string Root="Assets/EchoStation/SalvageExpansion",ScenePath=Root+"/Scenes/ES_EnvironmentalSalvage.unity",Generated=Root+"/Generated",NavPath=Generated+"/Nav.asset",RendererPath=Generated+"/ForwardRenderer.asset",Evidence="Docs/Tests/SalvagePrototype/Evidence/Expansion/B06";
        public static string Pipeline(int i)=>Generated+"/Expansion_"+i+"_ForwardHDR.asset";
        public static void RefineDeviceClearance()
        {
            SceneSafetyGuard.RequireClean();string nextNav=Generated+"/Nav_Clearance.asset";if(File.Exists(nextNav))throw new InvalidOperationException("Clearance refinement already exists.");var previous=SceneManager.GetActiveScene();var scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);try{SceneManager.SetActiveScene(scene);var root=scene.GetRootGameObjects().Single();var devices=root.GetComponentsInChildren<FacilityDevice>();devices.Single(d=>d.Kind==FacilityDeviceKind.FanSocket).transform.position=new Vector3(10.2f,.9f,20);devices.Single(d=>d.Kind==FacilityDeviceKind.Valve).transform.position=new Vector3(16,.9f,4.5f);var surface=root.GetComponent<NavMeshSurface>();surface.RemoveData();surface.navMeshData=null;surface.BuildNavMesh();AssetDatabase.CreateAsset(surface.navMeshData,nextNav);AssetDatabase.SaveAssetIfDirty(surface.navMeshData);if(!EditorSceneManager.SaveScene(scene))throw new IOException("Refined scene save failed.");File.WriteAllText(Evidence+"/Clearance_B.json",new JObject{{"fan",new JArray(10.2,.9,20)},{"valve",new JArray(16,.9,4.5)},{"newNav",nextNav},{"initialNavPreserved",File.Exists(NavPath)}}.ToString());}finally{SceneManager.SetActiveScene(previous);EditorSceneManager.CloseScene(scene,true);}
        }
        static void Copy(string from,string to){if(File.Exists(to)||!AssetDatabase.CopyAsset(from,to))throw new IOException("Preserve/create unique asset: "+to);}
        static Material Material(string name,Color color){var mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name,color=color,enableInstancing=true};AssetDatabase.CreateAsset(mat,Generated+"/"+name+".mat");AssetDatabase.SaveAssetIfDirty(mat);return mat;}
        static GameObject Cube(string name,Transform parent,Vector3 position,Vector3 size,Material mat){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(parent,false);go.transform.position=position;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=mat;return go;}
        static WorldTarget Target(GameObject go,string id,string label){bool active=go.activeSelf;go.SetActive(false);var target=go.AddComponent<WorldTarget>();target.Configure(id,label);go.AddComponent<EchoTargetPermissions>().Configure(true,false);go.SetActive(active);return target;}
        public static void Create()
        {
            SceneSafetyGuard.RequireClean();if(File.Exists(ScenePath))throw new InvalidOperationException("Keep existing expansion scene.");Directory.CreateDirectory(Generated);Directory.CreateDirectory(Root+"/Scenes");Directory.CreateDirectory(Evidence);AssetDatabase.Refresh();
            Copy(NextRendering.RendererPath,RendererPath);var renderer=AssetDatabase.LoadAssetAtPath<UniversalRendererData>(RendererPath);foreach(var f in renderer.rendererFeatures.Where(f=>f is NextFogFeature).ToArray()){renderer.rendererFeatures.Remove(f);if(AssetDatabase.GetAssetPath(f)!=RendererPath)throw new InvalidOperationException("Foreign renderer feature preserved.");Object.DestroyImmediate(f,true);}var fogFeature=ScriptableObject.CreateInstance<ExpansionFogFeature>();fogFeature.name="Expansion_StateDrivenFog";fogFeature.Configure(AssetDatabase.LoadAssetAtPath<Shader>(NextFogSetup.ShaderPath));AssetDatabase.AddObjectToAsset(fogFeature,renderer);renderer.rendererFeatures.Add(fogFeature);renderer.SetDirty();AssetDatabase.SaveAssetIfDirty(renderer);
            for(int i=0;i<3;i++){Copy(NextRendering.PipelinePath(i),Pipeline(i));var pipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(Pipeline(i));var so=new SerializedObject(pipeline);so.FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue=renderer;so.ApplyModifiedPropertiesWithoutUndo();AssetDatabase.SaveAssetIfDirty(pipeline);}
            Copy(NextArtV2Stream.Main,ScenePath);var previous=SceneManager.GetActiveScene();var scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);
            try
            {
                SceneManager.SetActiveScene(scene);var root=scene.GetRootGameObjects().Single();root.name="ES_EnvironmentalSalvage_World";foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)).ToArray())if(t&&PrefabUtility.IsPartOfPrefabInstance(t))PrefabUtility.UnpackPrefabInstance(t.gameObject,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);
                Object.DestroyImmediate(root.GetComponent<NextRenderScope>());if(root.GetComponent<NextFogField>())Object.DestroyImmediate(root.GetComponent<NextFogField>());if(root.GetComponent<NextFaultSparks>())Object.DestroyImmediate(root.GetComponent<NextFaultSparks>());
                var oldPlayer=root.GetComponentInChildren<SalvageMotor>().gameObject;var camera=Object.Instantiate(oldPlayer.GetComponent<SalvageMotor>().View.gameObject,root.transform).GetComponent<Camera>();camera.name="ExpansionView";camera.tag="MainCamera";foreach(var view in camera.GetComponents<NextFogView>())Object.DestroyImmediate(view);foreach(var view in camera.GetComponents<ScanWaveView>())Object.DestroyImmediate(view);var oldFocus=oldPlayer.GetComponent<NextFocus>().FocusVolume;var focus=Object.Instantiate(oldFocus.gameObject,root.transform).GetComponent<Volume>();focus.name="ExpansionFocusVolume";
                var oldRobot=root.GetComponentInChildren<SalvageEcho>().gameObject;Object.DestroyImmediate(oldRobot);foreach(var actor in root.GetComponentsInChildren<CargoActor>(true))Object.DestroyImmediate(actor.gameObject);foreach(var target in root.GetComponentsInChildren<SalvageTargetView>(true))if(target)Object.DestroyImmediate(target.gameObject);Object.DestroyImmediate(oldPlayer);
                var player=new GameObject("ExpansionPlayer");player.SetActive(false);player.transform.SetParent(root.transform,false);player.transform.position=new Vector3(5,.05f,12);player.transform.rotation=Quaternion.Euler(0,90,0);var body=player.AddComponent<CharacterController>();body.height=1.75f;body.radius=.3f;body.center=Vector3.up*.875f;body.stepOffset=.25f;body.skinWidth=.03f;var input=player.AddComponent<PlayerInputReader>();camera.transform.SetParent(player.transform,false);camera.transform.localPosition=Vector3.up*1.6f;camera.transform.localRotation=Quaternion.identity;camera.allowHDR=true;camera.GetUniversalAdditionalCameraData().allowHDROutput=false;camera.GetUniversalAdditionalCameraData().requiresDepthTexture=true;var motor=player.AddComponent<SalvageMotor>();motor.Configure(camera.transform);var torch=player.AddComponent<PlayerFlashlight>();torch.Configure(camera.GetComponentsInChildren<Light>(true).Single(l=>l.name=="Flashlight"));
                var itemMat=Material("ItemBlue",new Color(.25f,.5f,.65f));var toolMat=Material("ToolOrange",new Color(.85f,.45f,.15f));var deviceMat=Material("DeviceGray",new Color(.3f,.38f,.42f));var hazardMat=Material("HazardSignal",new Color(.7f,.3f,.05f));var container=new GameObject("ExpansionItems").transform;container.SetParent(root.transform,false);var positions=new[]{new Vector3(4,.32f,14),new Vector3(5,.32f,14),new Vector3(6,.32f,14),new Vector3(30,.32f,12),new Vector3(31,.32f,18),new Vector3(18,.32f,5),new Vector3(16,.32f,18)};var actors=new ExpansionItemActor[7];var targets=new System.Collections.Generic.List<WorldTarget>();for(int i=0;i<7;i++){var definition=ExpansionCatalog.Items[i];var go=Cube(definition.Name,container,positions[i],Vector3.one*.6f,i<3?toolMat:itemMat);actors[i]=go.AddComponent<ExpansionItemActor>();actors[i].Configure(definition.Id);if(i>=3)targets.Add(Target(go,definition.Id,definition.Name));}
                var world=player.AddComponent<ExpansionWorld>();world.Configure(motor,container,actors);player.AddComponent<ExpansionPersistence>();var devicePositions=new[]{new Vector3(10.2f,.9f,18),new Vector3(26,.9f,9),new Vector3(27,.9f,10),new Vector3(16,.9f,6),new Vector3(29,.55f,12),new Vector3(30,.55f,10.9f),new Vector3(31,.55f,12)};var devices=new FacilityDevice[7];for(int i=0;i<7;i++){var go=Cube("Facility_"+i,root.transform,devicePositions[i],Vector3.one*.4f,deviceMat);devices[i]=go.AddComponent<FacilityDevice>();devices[i].Configure((FacilityDeviceKind)i);targets.Add(Target(go,devices[i].Id,devices[i].DisplayName));}var facility=player.AddComponent<FacilityController>();facility.Configure(devices);var zones=new HazardZone[2];for(int i=0;i<2;i++){var go=new GameObject("HazardZone_"+i);go.transform.SetParent(root.transform,false);go.transform.position=i==0?new Vector3(12,1,18):new Vector3(30,1,12);var box=go.AddComponent<BoxCollider>();box.size=i==0?new Vector3(3,2,3):new Vector3(5,2,5);zones[i]=go.AddComponent<HazardZone>();zones[i].Configure((EnvironmentHazardKind)i);var plate=Cube("SignalFloor",go.transform,go.transform.position-Vector3.up*.98f,new Vector3(box.size.x,.02f,box.size.z),hazardMat);Object.DestroyImmediate(plate.GetComponent<Collider>());targets.Add(Target(go,i==0?"steam_zone":"electric_zone",i==0?"蒸汽通路":"漏电区域"));}var hazards=player.AddComponent<EnvironmentHazards>();hazards.Configure(zones);player.AddComponent<ExpansionTools>();
                var robot=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EchoStation/Echo/Prefabs/ES_Echo.prefab"),scene);PrefabUtility.UnpackPrefabInstance(robot,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);robot.name="ExpansionEcho";robot.transform.SetParent(root.transform,false);robot.transform.position=new Vector3(4,0,10);Object.DestroyImmediate(robot.GetComponent<EchoScanWaveBinding>());Object.DestroyImmediate(robot.GetComponent<EchoBrain>());Object.DestroyImmediate(robot.GetComponent<EchoScanController>());var appearance=robot.AddComponent<RoverAppearance>();appearance.Configure(AssetDatabase.LoadAssetAtPath<GameObject>(RoverAssets.PrefabPath).GetComponent<RoverModelParts>());if(!appearance.Mount())throw new InvalidOperationException("Rover mount failed.");var nav=robot.GetComponent<EchoNavigation>();nav.Agent.radius=.3f;nav.Agent.height=.6f;var echo=player.AddComponent<ExpansionEcho>();echo.Configure(nav,targets.ToArray());camera.gameObject.AddComponent<ScanWaveView>().Source=robot.GetComponent<ScanWaveEmitter>();
                var graphics=player.AddComponent<ExpansionGraphics>();graphics.Configure(Enumerable.Range(0,3).Select(i=>(RenderPipelineAsset)AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(Pipeline(i))).ToArray(),focus);player.AddComponent<ExpansionStreaming>();player.AddComponent<ExpansionMission>();var events=new GameObject("ExpansionEventSystem",typeof(EventSystem),typeof(InputSystemUIInputModule));events.transform.SetParent(player.transform,false);events.GetComponent<InputSystemUIInputModule>().AssignDefaultActions();
                var lights=root.GetComponentsInChildren<Light>(true).Where(l=>l.type!=LightType.Directional&&l.lightmapBakeType==LightmapBakeType.Realtime).ToArray();if(lights.Length!=4)throw new InvalidOperationException("Expected four realtime locals, got "+lights.Length);root.GetComponent<LocalShadowBudget>().Configure(camera,lights.Select(l=>l.GetUniversalAdditionalLightData()).ToArray());var fog=root.AddComponent<ExpansionFogField>();fog.Configure(hazards,graphics,lights);camera.gameObject.AddComponent<ExpansionFogView>().Source=fog;foreach(var shadows in root.GetComponentsInChildren<DistanceShadowCaster>(true))shadows.Configure(camera,shadows.GetComponentsInChildren<Renderer>(true),30,2,.1f);
                player.SetActive(true);var surface=root.GetComponent<NavMeshSurface>();surface.RemoveData();surface.navMeshData=null;surface.BuildNavMesh();if(!surface.navMeshData)throw new InvalidOperationException("Expansion navigation bake failed.");AssetDatabase.CreateAsset(surface.navMeshData,NavPath);AssetDatabase.SaveAssetIfDirty(surface.navMeshData);if(!EditorSceneManager.SaveScene(scene))throw new IOException("Scene save failed.");File.WriteAllText(Evidence+"/Created_A.json",new JObject{{"scene",ScenePath},{"nav",NavPath},{"targets",targets.Count},{"items",actors.Length},{"devices",devices.Length},{"realtimeLights",lights.Length},{"oldScenesPreserved",true}}.ToString());
            }
            finally{SceneManager.SetActiveScene(previous);EditorSceneManager.CloseScene(scene,true);}
        }
